lexicon = []
seen = set()
for word, trans, phon, pos, defn, ex, syns, ants in ENTRIES:
    key = word.lower().strip()
    if key in seen:
        continue
    seen.add(key)
    lexicon.append({
        "word": word,
        "translation": trans,
        "phonetic": phon,
        "partOfSpeech": pos,
        "definition": defn,
        "example": ex,
        "synonyms": syns,
        "antonyms": ants
    })

os.makedirs("app/src/main/assets", exist_ok=True)
with open("app/src/main/assets/global_lexicon.json", "w", encoding="utf-8") as f:
    json.dump(lexicon, f, ensure_ascii=False, indent=2)

print(f"Wrote {len(lexicon)} entries to app/src/main/assets/global_lexicon.json")
